// TypeScript Version: 4.1

/**
* Returns the mode of a Burr (type III) distribution with first shape parameter `c` and second shape parameter `d`.
*
* ## Notes
*
* -   If provided `c <= 0` or `d <= 0`, the function returns `NaN`.
* -   If provided `c` and `d` such that `c * d <= 1`, the function returns `0.0`.
*
* @param c - first shape parameter
* @param d - second shape parameter
* @returns mode
*
* @example
* var y = mode( 2.0, 1.0 );
* // returns ~0.577
*
* @example
* var y = mode( 4.0, 12.0 );
* // returns ~1.751
*
* @example
* var y = mode( 1.0, 1.0 );
* // returns 0.0
*
* @example
* var y = mode( NaN, 2.0 );
* // returns NaN
*
* @example
* var y = mode( 2.0, NaN );
* // returns NaN
*
* @example
* var y = mode( -1.0, 2.0 );
* // returns NaN
*
* @example
* var y = mode( 2.0, -1.0 );
* // returns NaN
*/
declare function mode( c: number, d: number ): number;


// EXPORTS //

export = mode;
